package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.ScreenFamily;
import net.minecraft.world.phys.AABB;
/** Compare emitted native block boxes to independently frozen actual Source block queries. */
public final class ScreenGeometryChecks {
 public static void main(String[] args)throws Exception {JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenGeometryReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0,boxes=0;for(var entry:reference.getAsJsonArray("cases")){var expected=entry.getAsJsonObject();ScreenFamily family=ScreenFamily.fromId(expected.get("id").getAsString());int ceiling=expected.get("ceiling").getAsInt();var actual=NativeScreenGeometry.of(family,family.decode(expected.get("meta").getAsInt()),expected.get("small").getAsBoolean(),expected.get("wall").getAsInt(),ceiling>=0,ceiling);compare(actual.bounds(),expected.getAsJsonArray("bounds"));var collision=expected.getAsJsonArray("collision");if(actual.collision().size()!=collision.size())throw new AssertionError("Collision count "+expected);for(int i=0;i<collision.size();i++){compare(actual.collision().get(i),collision.get(i).getAsJsonArray());boxes++;}try{actual.collision().clear();throw new AssertionError("Mutable geometry");}catch(UnsupportedOperationException expectedImmutable){}cases++;}if(cases!=2240||boxes!=8768||!reference.get("sha256").getAsString().equals("83ede38318365cfad58149c9bb770d2ee211aa96d80dccc0f0aeec0768c779af"))throw new AssertionError("Source coverage changed");System.out.println("Native Screen block geometry PASS cases="+cases+" collisionBoxes="+boxes+" exact Source bounds; precise diagonal rays remain separate");}
 private static void compare(AABB actual,JsonArray expected){double[] values={actual.minX,actual.minY,actual.minZ,actual.maxX,actual.maxY,actual.maxZ};for(int i=0;i<6;i++)if(Math.abs(values[i]-expected.get(i).getAsDouble())>1e-12)throw new AssertionError("Box differs "+actual+" expected "+expected);}
}
